    import polars as pl
    return

@app.cell
def _():
    # Load dataset
    weather = pl.read_csv("&lt;https://raw.githubusercontent.com/vega/vega-datasets/refs/heads/main/data/weather.csv&gt;")
    weather_dates = weather.with_columns(
        pl.col("date").str.strptime(pl.Date, format="%Y-%m-%d")
    )
    _chart = (
        alt.Chart(weather_dates)
        .mark_point()
        .encode(
            x="date:T",
            y="temp_max",
            color="location",
        )
    )
    return

